import React, { useState } from 'react';
import {
  Box,
  Button,
  TextField,
  Typography,
  Paper,
  Table,
  TableHead,
  TableRow,
  TableCell,
  TableBody
} from '@mui/material';
import styles from './AutomatedSegmentation.module.css';

// Тестовые данные (пример RFM метрик)
const testClients = [
  { customer_id: 1, recency: 10, frequency: 5, monetary: 200 },
  { customer_id: 2, recency: 30, frequency: 2, monetary: 50 },
  { customer_id: 3, recency: 5,  frequency: 8, monetary: 300 },
  { customer_id: 4, recency: 20, frequency: 3, monetary: 100 },
  { customer_id: 5, recency: 15, frequency: 4, monetary: 150 },
  { customer_id: 6, recency: 40, frequency: 1, monetary: 80 },
  // Дополните набор тестовыми данными по необходимости
];

// Функция для вычисления евклидова расстояния между двумя точками (используются RFM метрики)
function distance(pointA, pointB) {
  return Math.sqrt(
    Math.pow(pointA.recency - pointB.recency, 2) +
    Math.pow(pointA.frequency - pointB.frequency, 2) +
    Math.pow(pointA.monetary - pointB.monetary, 2)
  );
}

// Простейшая реализация алгоритма K‑means
function kmeans(data, k, maxIterations = 100) {
  // Инициализация центроидов: случайный выбор k точек
  let centroids = [];
  const dataCopy = [...data];
  for (let i = 0; i < k; i++) {
    const randomIndex = Math.floor(Math.random() * dataCopy.length);
    centroids.push({ ...dataCopy[randomIndex] });
    dataCopy.splice(randomIndex, 1);
  }
  
  let assignments = new Array(data.length).fill(0);
  let iterations = 0;
  let change = true;
  
  while (change && iterations < maxIterations) {
    change = false;
    // Присвоение каждой точки ближайшего центроида
    for (let i = 0; i < data.length; i++) {
      const distances = centroids.map(c => distance(data[i], c));
      const minDistance = Math.min(...distances);
      const newAssignment = distances.indexOf(minDistance);
      if (assignments[i] !== newAssignment) {
        assignments[i] = newAssignment;
        change = true;
      }
    }
    
    // Пересчёт центроидов
    let newCentroids = Array(k).fill(null).map(() => ({ recency: 0, frequency: 0, monetary: 0, count: 0 }));
    
    data.forEach((point, idx) => {
      const cluster = assignments[idx];
      newCentroids[cluster].recency += point.recency;
      newCentroids[cluster].frequency += point.frequency;
      newCentroids[cluster].monetary += point.monetary;
      newCentroids[cluster].count += 1;
    });
    
    for (let i = 0; i < k; i++) {
      if (newCentroids[i].count > 0) {
        centroids[i] = {
          recency: newCentroids[i].recency / newCentroids[i].count,
          frequency: newCentroids[i].frequency / newCentroids[i].count,
          monetary: newCentroids[i].monetary / newCentroids[i].count,
        };
      }
    }
    iterations++;
  }
  
  return { assignments, centroids };
}

const AutomatedSegmentation = () => {
  const [clients] = useState(testClients);
  const [k, setK] = useState(2);
  const [segmentationResult, setSegmentationResult] = useState(null);

  const runSegmentation = () => {
    if (clients.length === 0) return;
    const result = kmeans(clients, k);
    setSegmentationResult(result);
  };

  return (
    <Box className={styles.container}>
      <Typography variant="h4" gutterBottom>
        Автоматизированная сегментация клиентов
      </Typography>
      <Typography variant="body1" gutterBottom>
        Используйте RFM метрики (Срок давности, Частота, Сумма) для сегментации клиентов.
      </Typography>
      <Box mb={2} display="flex" alignItems="center" gap={2}>
        <TextField
          label="Количество кластеров (k)"
          type="number"
          variant="outlined"
          value={k}
          onChange={(e) => setK(Number(e.target.value))}
        />
        <Button variant="contained" onClick={runSegmentation}>
          Запустить сегментацию
        </Button>
      </Box>
      {segmentationResult && (
        <Paper sx={{ mt: 3, p: 2 }}>
          <Typography variant="h6" gutterBottom>
            Результаты сегментации
          </Typography>
          <Table>
            <TableHead>
              <TableRow>
                <TableCell>ID клиента</TableCell>
                <TableCell>Recency</TableCell>
                <TableCell>Frequency</TableCell>
                <TableCell>Monetary</TableCell>
                <TableCell>Сегмент</TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {clients.map((client, idx) => (
                <TableRow key={client.customer_id || idx}>
                  <TableCell>{client.customer_id || idx + 1}</TableCell>
                  <TableCell>{client.recency}</TableCell>
                  <TableCell>{client.frequency}</TableCell>
                  <TableCell>{client.monetary}</TableCell>
                  <TableCell>{segmentationResult.assignments[idx]}</TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
          <Box mt={2}>
            <Typography variant="subtitle1">
              Центроиды кластеров:
            </Typography>
            {segmentationResult.centroids.map((centroid, idx) => (
              <Typography key={idx} variant="body2">
                Кластер {idx}: Recency: {centroid.recency.toFixed(1)}, Frequency: {centroid.frequency.toFixed(1)}, Monetary: {centroid.monetary.toFixed(1)}
              </Typography>
            ))}
          </Box>
        </Paper>
      )}
    </Box>
  );
};

export default AutomatedSegmentation;