import React, { useState } from 'react';
import Papa from 'papaparse';
import ReactQuill from 'react-quill';
import 'react-quill/dist/quill.snow.css';
import {
  Box,
  TextField,
  Button,
  Typography,
  Snackbar,
  Alert,
  Tooltip,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
  OutlinedInput,
  Chip,
  Switch,
  FormControlLabel,
  Accordion,
  AccordionSummary,
  AccordionDetails
} from '@mui/material';
import ExpandMoreIcon from '@mui/icons-material/ExpandMore';
import styles from './MailingSetup.css';

const EMAIL_REGEX = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

// Пример шаблонов (если нужно)
const templates = [
  {
    name: 'Шаблон 1',
    subject: 'Добро пожаловать!',
    content: '<p>Здравствуйте, спасибо за регистрацию!</p>'
  },
  {
    name: 'Шаблон 2',
    subject: 'Скидка для вас',
    content: '<p>У нас для вас специальное предложение!</p>'
  }
];

const recurrenceOptions = [
  { value: 'once', label: 'Однократная' },
  { value: 'daily', label: 'Ежедневно' },
  { value: 'weekly', label: 'Еженедельно' },
  { value: 'monthly', label: 'Ежемесячно' }
];

const channelOptions = [
  { value: 'email', label: 'Email' },
  { value: 'sms', label: 'SMS' },
  { value: 'push', label: 'Push' },
  { value: 'telegram', label: 'Telegram' },
  { value: 'social', label: 'Соц. сети' }
];

const MailingSetup = () => {
  // Основные состояния формы
  const [recipients, setRecipients] = useState('');
  const [scheduledTime, setScheduledTime] = useState('');
  const [recurrence, setRecurrence] = useState('once');
  const [selectedChannels, setSelectedChannels] = useState(['email']); // По умолчанию Email
  const [attachments, setAttachments] = useState([]);
  const [previewVisible, setPreviewVisible] = useState(false);
  const [previewMode, setPreviewMode] = useState('desktop'); // 'desktop' | 'mobile'
  const [loading, setLoading] = useState(false);
  const [alert, setAlert] = useState({ open: false, severity: 'info', message: '' });

  // Каскадная отправка
  const [cascade, setCascade] = useState(false);
  const [cascadeOrder, setCascadeOrder] = useState('');

  // Настройки для каждого канала
  // Перенесли сюда поля "subject" и "content" только для Email
  const [channelSettings, setChannelSettings] = useState({
    email: {
      sender: '',
      signature: '',
      emailMessage: '',
      emailSubject: '',    // Тема письма
      emailContent: ''     // Содержимое письма (ReactQuill)
    },
    sms: {
      senderId: '',
      messageLimit: 160,
      smsMessage: ''
    },
    push: {
      pushTitle: '',
      pushMessage: ''
    },
    telegram: {
      chatId: '',
      botToken: '',
      telegramMessage: ''
    },
    social: {
      postLink: '',
      socialMessage: ''
    }
  });

  // Валидация email-адресов
  const validateEmails = (emailsString) => {
    const emails = emailsString
      .split(',')
      .map(email => email.trim())
      .filter(email => email);
    const invalidEmails = emails.filter(email => !EMAIL_REGEX.test(email));
    return { emails, invalidEmails };
  };

  const handleRecipientsChange = (e) => {
    setRecipients(e.target.value);
  };

  // Загрузка CSV
  const handleCSVUpload = (e) => {
    const file = e.target.files[0];
    if (file) {
      Papa.parse(file, {
        header: false,
        complete: (results) => {
          const emails = results.data.flat().join(', ');
          setRecipients(prev => prev ? prev + ', ' + emails : emails);
        },
        error: (error) => {
          setAlert({ open: true, severity: 'error', message: 'Ошибка при загрузке CSV: ' + error.message });
        }
      });
    }
  };

  // Обработка выбора каналов
  const handleChannelsChange = (event) => {
    const { target: { value } } = event;
    setSelectedChannels(typeof value === 'string' ? value.split(',') : value);
  };

  // Каскадная отправка
  const handleCascadeChange = (event) => {
    setCascade(event.target.checked);
  };

  const handleCascadeOrderChange = (e) => {
    setCascadeOrder(e.target.value);
  };

  // Изменения настроек конкретного канала
  const handleChannelSettingChange = (channel, field, value) => {
    setChannelSettings(prev => ({
      ...prev,
      [channel]: {
        ...prev[channel],
        [field]: value
      }
    }));
  };

  // Отправка формы
  const handleSubmit = (e) => {
    e.preventDefault();
    // Проверка на наличие получателей
    if (!recipients) {
      setAlert({ open: true, severity: 'error', message: 'Пожалуйста, введите список получателей (email).' });
      return;
    }
    // Валидация email для тех каналов, где email-адреса нужны
    if (selectedChannels.includes('email')) {
      const { invalidEmails } = validateEmails(recipients);
      if (invalidEmails.length > 0) {
        setAlert({ open: true, severity: 'error', message: 'Некорректные email адреса: ' + invalidEmails.join(', ') });
        return;
      }
      // Проверим, заполнены ли "Тема письма" и "Содержимое письма" в email-настройках
      if (!channelSettings.email.emailSubject || !channelSettings.email.emailContent) {
        setAlert({ open: true, severity: 'error', message: 'Заполните тему и содержимое письма в настройках Email.' });
        return;
      }
    }

    // Имитация отправки
    setLoading(true);
    setAlert({ open: true, severity: 'info', message: 'Запуск рассылки по каналам: ' + selectedChannels.join(', ') });
    console.log('Данные рассылки:', {
      recipients,
      scheduledTime,
      recurrence,
      selectedChannels,
      cascade,
      cascadeOrder,
      channelSettings,
      attachments
    });
    setTimeout(() => {
      setLoading(false);
      setAlert({ open: true, severity: 'success', message: 'Рассылка успешно запущена!' });
      // Очистка формы
      setRecipients('');
      setScheduledTime('');
      setRecurrence('once');
      setSelectedChannels(['email']);
      setCascade(false);
      setCascadeOrder('');
      setChannelSettings({
        email: {
          sender: '',
          signature: '',
          emailMessage: '',
          emailSubject: '',
          emailContent: ''
        },
        sms: { senderId: '', messageLimit: 160, smsMessage: '' },
        push: { pushTitle: '', pushMessage: '' },
        telegram: { chatId: '', botToken: '', telegramMessage: '' },
        social: { postLink: '', socialMessage: '' }
      });
      setAttachments([]);
      setPreviewVisible(false);
    }, 1500);
  };

  // Предпросмотр (только для Email-содержимого, т.к. это HTML)
  const handlePreview = () => {
    if (!channelSettings.email.emailSubject || !channelSettings.email.emailContent) {
      setAlert({ open: true, severity: 'error', message: 'Сначала заполните тему и содержимое письма (Email).' });
      return;
    }
    setPreviewVisible(true);
  };

  const handleAttachmentChange = (e) => {
    const files = Array.from(e.target.files);
    setAttachments(files);
  };

  return (
    <Box className={styles.container}>
      <Typography variant="h4" className={styles.title} gutterBottom>
        Настройка и запуск рассылок
      </Typography>

      <form onSubmit={handleSubmit} className={styles.form}>
        <Tooltip title="Введите email-адреса получателей, разделённые запятыми" arrow>
          <TextField
            label="Список получателей (email)"
            variant="outlined"
            fullWidth
            value={recipients}
            onChange={handleRecipientsChange}
            margin="normal"
            required={selectedChannels.includes('email')} 
          />
        </Tooltip>
        
        <Box marginY={1}>
          <Button variant="outlined" component="label">
            Загрузить CSV
            <input type="file" accept=".csv" hidden onChange={handleCSVUpload} />
          </Button>
        </Box>

        <Box marginY={2}>
          <FormControl fullWidth>
            <InputLabel id="channels-select-label">Каналы отправки</InputLabel>
            <Select
              labelId="channels-select-label"
              multiple
              value={selectedChannels}
              onChange={handleChannelsChange}
              input={<OutlinedInput label="Каналы отправки" />}
              renderValue={(selected) => (
                <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 0.5 }}>
                  {selected.map((value) => (
                    <Chip key={value} label={channelOptions.find(opt => opt.value === value)?.label || value} />
                  ))}
                </Box>
              )}
            >
              {channelOptions.map((option) => (
                <MenuItem key={option.value} value={option.value}>
                  {option.label}
                </MenuItem>
              ))}
            </Select>
          </FormControl>
        </Box>

        <Box marginY={2}>
          <FormControlLabel
            control={<Switch checked={cascade} onChange={handleCascadeChange} color="primary" />}
            label="Отправлять каскадом"
          />
          {cascade && (
            <TextField 
              label="Порядок отправки (например: email, sms, push)" 
              variant="outlined" 
              fullWidth 
              value={cascadeOrder}
              onChange={handleCascadeOrderChange}
              margin="normal"
            />
          )}
        </Box>

        <Box marginY={2}>
          <TextField
            label="Запланированное время (опционально)"
            type="datetime-local"
            variant="outlined"
            fullWidth
            value={scheduledTime}
            onChange={(e) => setScheduledTime(e.target.value)}
            InputLabelProps={{ shrink: true }}
          />
        </Box>

        <Box marginY={2}>
          <FormControl fullWidth>
            <InputLabel id="recurrence-select-label">Повторение рассылки</InputLabel>
            <Select
              labelId="recurrence-select-label"
              value={recurrence}
              label="Повторение рассылки"
              onChange={(e) => setRecurrence(e.target.value)}
            >
              {recurrenceOptions.map(option => (
                <MenuItem key={option.value} value={option.value}>{option.label}</MenuItem>
              ))}
            </Select>
          </FormControl>
        </Box>

        <Box marginY={2}>
          <Button variant="outlined" component="label">
            Прикрепить файлы
            <input type="file" multiple hidden onChange={handleAttachmentChange} />
          </Button>
          {attachments.length > 0 && (
            <Typography variant="body2" marginTop={1}>
              {attachments.length} файл(а) выбрано.
            </Typography>
          )}
        </Box>

        <Box marginTop={3} display="flex" gap={2}>
          <Button variant="contained" color="primary" type="submit" disabled={loading}>
            {loading ? 'Запуск...' : 'Запустить рассылку'}
          </Button>
          <Button variant="outlined" onClick={handlePreview}>
            Предпросмотр (Email)
          </Button>
        </Box>
      </form>

      {/* Настройки для каждого канала */}
      {selectedChannels.map((channel) => (
        <Accordion key={channel} defaultExpanded>
          <AccordionSummary expandIcon={<ExpandMoreIcon />}>
            <Typography variant="subtitle1">
              Настройки для {channel === 'email'
                ? 'Email'
                : channel === 'sms'
                ? 'SMS'
                : channel === 'push'
                ? 'Push'
                : channel === 'telegram'
                ? 'Telegram'
                : 'Соц. сети'}
            </Typography>
          </AccordionSummary>
          <AccordionDetails>
            {/* Если канал = email, показываем Тему и Содержимое письма */}
            {channel === 'email' && (
              <Box>
                <TextField 
                  label="Отправитель (Email)" 
                  variant="outlined" 
                  fullWidth 
                  value={channelSettings.email.sender}
                  onChange={(e) => handleChannelSettingChange('email', 'sender', e.target.value)}
                  margin="normal"
                />
                <TextField 
                  label="Подпись" 
                  variant="outlined" 
                  fullWidth 
                  value={channelSettings.email.signature}
                  onChange={(e) => handleChannelSettingChange('email', 'signature', e.target.value)}
                  margin="normal"
                />
                <TextField 
                  label="Тема письма" 
                  variant="outlined" 
                  fullWidth
                  required={selectedChannels.includes('email')}
                  value={channelSettings.email.emailSubject}
                  onChange={(e) => handleChannelSettingChange('email', 'emailSubject', e.target.value)}
                  margin="normal"
                />
                <Box marginY={2}>
                  <Typography variant="subtitle1" gutterBottom>Содержимое письма</Typography>
                  <ReactQuill
                    value={channelSettings.email.emailContent}
                    onChange={(val) => handleChannelSettingChange('email', 'emailContent', val)}
                    placeholder="Введите содержимое письма..."
                  />
                </Box>
                <TextField 
                  label="Доп. сообщение для Email" 
                  variant="outlined" 
                  fullWidth 
                  multiline
                  rows={2}
                  value={channelSettings.email.emailMessage}
                  onChange={(e) => handleChannelSettingChange('email', 'emailMessage', e.target.value)}
                  margin="normal"
                />
              </Box>
            )}
            {channel === 'sms' && (
              <Box>
                <TextField 
                  label="Sender ID (SMS)" 
                  variant="outlined" 
                  fullWidth 
                  value={channelSettings.sms.senderId}
                  onChange={(e) => handleChannelSettingChange('sms', 'senderId', e.target.value)}
                  margin="normal"
                />
                <TextField 
                  label="Максимальная длина сообщения" 
                  type="number"
                  variant="outlined" 
                  fullWidth 
                  value={channelSettings.sms.messageLimit}
                  onChange={(e) => handleChannelSettingChange('sms', 'messageLimit', e.target.value)}
                  margin="normal"
                />
                <TextField 
                  label="Текст SMS сообщения" 
                  variant="outlined" 
                  fullWidth 
                  multiline
                  rows={2}
                  value={channelSettings.sms.smsMessage}
                  onChange={(e) => handleChannelSettingChange('sms', 'smsMessage', e.target.value)}
                  margin="normal"
                />
              </Box>
            )}
            {channel === 'push' && (
              <Box>
                <TextField 
                  label="Заголовок Push" 
                  variant="outlined" 
                  fullWidth 
                  value={channelSettings.push.pushTitle}
                  onChange={(e) => handleChannelSettingChange('push', 'pushTitle', e.target.value)}
                  margin="normal"
                />
                <TextField 
                  label="Сообщение Push" 
                  variant="outlined" 
                  fullWidth 
                  multiline
                  rows={2}
                  value={channelSettings.push.pushMessage}
                  onChange={(e) => handleChannelSettingChange('push', 'pushMessage', e.target.value)}
                  margin="normal"
                />
              </Box>
            )}
            {channel === 'telegram' && (
              <Box>
                <TextField 
                  label="Chat ID" 
                  variant="outlined" 
                  fullWidth 
                  value={channelSettings.telegram.chatId}
                  onChange={(e) => handleChannelSettingChange('telegram', 'chatId', e.target.value)}
                  margin="normal"
                />
                <TextField 
                  label="Bot Token" 
                  variant="outlined" 
                  fullWidth 
                  value={channelSettings.telegram.botToken}
                  onChange={(e) => handleChannelSettingChange('telegram', 'botToken', e.target.value)}
                  margin="normal"
                />
                <TextField 
                  label="Текст Telegram сообщения" 
                  variant="outlined" 
                  fullWidth 
                  multiline
                  rows={2}
                  value={channelSettings.telegram.telegramMessage}
                  onChange={(e) => handleChannelSettingChange('telegram', 'telegramMessage', e.target.value)}
                  margin="normal"
                />
              </Box>
            )}
            {channel === 'social' && (
              <Box>
                <TextField 
                  label="Ссылка для поста" 
                  variant="outlined" 
                  fullWidth 
                  value={channelSettings.social.postLink}
                  onChange={(e) => handleChannelSettingChange('social', 'postLink', e.target.value)}
                  margin="normal"
                />
                <TextField 
                  label="Текст сообщения для соц. сетей" 
                  variant="outlined" 
                  fullWidth 
                  multiline
                  rows={2}
                  value={channelSettings.social.socialMessage}
                  onChange={(e) => handleChannelSettingChange('social', 'socialMessage', e.target.value)}
                  margin="normal"
                />
              </Box>
            )}
          </AccordionDetails>
        </Accordion>
      ))}

      {/* Предпросмотр только для Email-содержимого */}
      {previewVisible && (
        <Box className={styles.preview}>
          <Box display="flex" justifyContent="space-between" alignItems="center" mb={2}>
            <Typography variant="h6">Предпросмотр письма (Email)</Typography>
            <FormControlLabel
              control={
                <Switch
                  checked={previewMode === 'mobile'}
                  onChange={(e) => setPreviewMode(e.target.checked ? 'mobile' : 'desktop')}
                  color="primary"
                />
              }
              label="Mobile view"
            />
          </Box>
          <Box className={previewMode === 'mobile' ? styles.mobilePreview : styles.desktopPreview}>
            <Typography variant="subtitle1" gutterBottom>
              Тема: {channelSettings.email.emailSubject}
            </Typography>
            <div dangerouslySetInnerHTML={{ __html: channelSettings.email.emailContent }} />
            {attachments.length > 0 && (
              <Box mt={2}>
                <Typography variant="subtitle2">Вложения:</Typography>
                <Box display="flex" gap={2}>
                  {attachments.map((file, index) => {
                    if (file.type.startsWith('image/')) {
                      return (
                        <img
                          key={index}
                          src={URL.createObjectURL(file)}
                          alt={`attachment-${index}`}
                          className={styles.attachmentPreview}
                        />
                      );
                    }
                    return (
                      <Typography key={index} variant="body2">
                        {file.name}
                      </Typography>
                    );
                  })}
                </Box>
              </Box>
            )}
          </Box>
          <Box mt={2} display="flex" justifyContent="flex-end">
            <Button variant="text" onClick={() => setPreviewVisible(false)}>
              Закрыть предпросмотр
            </Button>
          </Box>
        </Box>
      )}

      <Snackbar
        open={alert.open}
        autoHideDuration={3000}
        onClose={() => setAlert({ ...alert, open: false })}
      >
        <Alert severity={alert.severity} onClose={() => setAlert({ ...alert, open: false })} sx={{ width: '100%' }}>
          {alert.message}
        </Alert>
      </Snackbar>
    </Box>
  );
};

export default MailingSetup;