// src/components/MainContent/MainContent.jsx
import React from 'react';
import ProductAnalytics from '../ProductAnalytics/ProductAnalytics';
import RFMAnalysisDashboard from '../RFMAnalysisDashboard/RFMAnalysisDashboard';
import ClientFilter from '../ClientFilter/ClientFilter';
import LoyaltySettings from '../LoyaltySettings/LoyaltySettings';
import CardConstructor from '../CardConstructor/CardConstructor';
import Dashboard from '../Dashboard/Dashboard';
import MailingSetup from '../MailingSetup/MailingSetup';
import AutomatedSegmentation from '../AutomatedSegmentation/AutomatedSegmentation';
import TriggerMailings from '../TriggerMailings/TriggerMailings';
import CouponGenerator from '../CouponGenerator/CouponGenerator';
import SocialListening from '../SocialListening/SocialListening';
import './MainContent.css';


const MainContent = ({ selectedTool }) => {
  const renderTool = () => {
    switch (selectedTool) {
      case 'ProductAnalytics':
        return <ProductAnalytics />;
      case 'RFMAnalysisDashboard':
        return <RFMAnalysisDashboard />;
      case 'ClientFilter':
        return <ClientFilter />;
      case 'LoyaltySettings':
        return <LoyaltySettings />;
      case 'CardConstructor':
        return <CardConstructor />;
      case 'Dashboard':
        return <Dashboard />;
      case 'MailingSetup':
        return <MailingSetup />;
      case 'AutomatedSegmentation':
        return <AutomatedSegmentation />;
      case 'TriggerMailings':
        return <TriggerMailings />;
      case 'CouponGenerator':
        return <CouponGenerator />;
      case 'SocialListening':
        return <SocialListening />;
      default:
        return <div style={{ padding: '20px' }}>Выберите инструмент из меню</div>;
    }
  };

  return <div className="main-content">{renderTool()}</div>;
};

export default MainContent;