// Функция фильтрации данных
const applyFilters = (
  row,
  dateFrom,
  dateTo,
  selectedReactions,
  selectedSegment,
  selectedVariant,
  searchTerm
) => {
  const rowDate = new Date(row.date);
  const from = dateFrom ? new Date(dateFrom) : null;
  const to = dateTo ? new Date(dateTo) : null;
  if (from && rowDate < from) return false;
  if (to && rowDate > to) return false;
  if (selectedReactions.length && !selectedReactions.includes(row["Название реакции"])) return false;
  if (selectedSegment.length && !selectedSegment.includes(row.segment)) return false;
  if (selectedVariant.length && !selectedVariant.includes(row.variant)) return false;
  if (searchTerm && !row["Название реакции"].toLowerCase().includes(searchTerm.toLowerCase()))
    return false;
  return true;
};

// Компонент Bar Chart
const BarChartComponent = ({ data, title, datasets, onElementClick }) => {
  const chartData = {
    labels: data.map(row => row["Название реакции"]),
    datasets: datasets.map(ds => ({
      label: ds.label,
      data: data.map(row => row[ds.field]),
      backgroundColor: ds.backgroundColor,
    })),
  };

  return (
    <Box mb={4}>
      <Typography variant="h6" align="center" gutterBottom>{title}</Typography>
      <Bar
        data={chartData}
        options={{
          responsive: true,
          plugins: { legend: { position: 'top' } },
          onClick: (event, elements) => {
            if (elements?.length && onElementClick) {
              const index = elements[0].index;
              onElementClick(data[index]);
            }
          },
        }}
      />
    </Box>
  );
};

// Компонент Scatter Chart
const ScatterChart = ({ data, title, onElementClick }) => {
  const chartData = {
    datasets: [
      {
        label: title,
        data: data.map(row => ({
          x: row["Конверсия, %"],
          y: row["Средний чек"],
          label: row["Название реакции"],
        })),
        backgroundColor: 'rgba(153, 102, 255, 0.6)',
      },
    ],
  };

  return (
    <Box mb={4}>
      <Typography variant="h6" align="center" gutterBottom>{title}</Typography>
      <Scatter
        data={chartData}
        options={{
          responsive: true,
          plugins: {
            tooltip: {
              callbacks: {
                label: (context) =>
                  `${context.raw.label}: (${context.raw.x}, ${context.raw.y})`,
              },
            },
            legend: { position: 'top' },
          },
          onClick: (event, elements) => {
            if (elements?.length && onElementClick) {
              const index = elements[0].index;
              onElementClick(data[index]);
            }
          },
          scales: {
            x: { title: { display: true, text: 'Конверсия, %' } },
            y: { title: { display: true, text: 'Средний чек' } },
          },
        }}
      />
    </Box>
  );
};

// Компонент Line Chart
const LineChart = ({ data, title, onElementClick }) => {
  const sortedData = [...data].sort((a, b) => new Date(a.date) - new Date(b.date));
  const labels = sortedData.map((row, idx) => `Кампания ${idx + 1}`);
  const values = sortedData.map(row => row["Средний чек"]);
  let predicted = null;
  if (values.length >= 2) {
    const diff = values[values.length - 1] - values[values.length - 2];
    predicted = values[values.length - 1] + diff;
  }
  const forecastLabels = [...labels, "Прогноз"];
  const forecastValues = predicted !== null ? [...values, predicted] : values;
  const chartData = {
    labels: forecastLabels,
    datasets: [
      {
        label: "Средний чек",
        data: forecastValues,
        fill: false,
        borderColor: 'rgba(75,192,192,1)',
      },
    ],
  };

  return (
    <Box mb={4}>
      <Typography variant="h6" align="center" gutterBottom>{title}</Typography>
      <Line
        data={chartData}
        options={{
          responsive: true,
          plugins: { legend: { position: 'top' } },
          onClick: (event, elements) => {
            if (elements?.length && onElementClick) {
              const index = elements[0].index;
              onElementClick(sortedData[index]);
            }
          },
        }}
      />
    </Box>
  );
};

// Компонент Funnel Chart
const FunnelChart = ({ data, title }) => {
  const totalRecipients = data.reduce((acc, row) => acc + row["Получателей"], 0);
  const totalResponded = data.reduce((acc, row) => acc + row["Среагировавших"], 0);
  const totalPurchases = data.reduce((acc, row) => acc + row["Чеков"], 0);
  const chartData = {
    labels: ["Получатели", "Среагировавшие", "Чеков"],
    datasets: [
      {
        label: title,
        data: [totalRecipients, totalResponded, totalPurchases],
        backgroundColor: [
          'rgba(75,192,192,0.6)',
          'rgba(153,102,255,0.6)',
          'rgba(255,159,64,0.6)',
        ],
      },
    ],
  };

  return (
    <Box mb={4}>
      <Typography variant="h6" align="center" gutterBottom>{title}</Typography>
      <Bar
        data={chartData}
        options={{
          indexAxis: 'y',
          responsive: true,
          plugins: { legend: { position: 'top' } },
        }}
      />
    </Box>
  );
};

// Компонент A/B Test Chart
const ABTestChart = ({ data, title, onElementClick }) => {
  const variants = Array.from(new Set(data.map(row => row.variant)));
  const chartData = {
    labels: variants,
    datasets: [
      {
        label: "Средняя конверсия, %",
        data: variants.map(v =>
          data.filter(row => row.variant === v)
            .reduce((sum, row) => sum + row["Конверсия, %"], 0) /
          data.filter(row => row.variant === v).length
        ),
        backgroundColor: variants.map((_, i) =>
          i % 2 === 0 ? 'rgba(75,192,192,0.6)' : 'rgba(255,99,132,0.6)'
        ),
      },
    ],
  };

  return (
    <Box mb={4}>
      <Typography variant="h6" align="center" gutterBottom>{title}</Typography>
      <Bar
        data={chartData}
        options={{
          responsive: true,
          plugins: { legend: { position: 'top' } },
          onClick: (event, elements) => {
            if (elements?.length && onElementClick) {
              const variant = chartData.labels[elements[0].index];
              const filtered = data.filter(row => row.variant === variant);
              onElementClick({ variant, details: filtered });
            }
          },
        }}
      />
    </Box>
  );
};

